import * as React from "react";
import { cx } from "./cx";

export interface AlertProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "title"> {
  title?: React.ReactNode;
  /** Solid ink variant. */
  variant?: "outline" | "solid";
  icon?: React.ReactNode;
}

export function Alert({ title, variant = "outline", icon, className, children, ...props }: AlertProps) {
  return (
    <div
      role="status"
      className={cx("rs-alert", variant === "solid" && "rs-alert-solid", className)}
      {...props}
    >
      {icon ?? (
        <svg viewBox="0 0 16 16" width="16" height="16" fill="none" aria-hidden="true">
          <circle cx="8" cy="8" r="6.25" stroke="currentColor" strokeWidth="1.5" />
          <path d="M8 7.5v3.5M8 5v.5" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" />
        </svg>
      )}
      <div>
        {title != null && <span className="rs-alert-title">{title}</span>}
        {children != null && <p className="rs-alert-body">{children}</p>}
      </div>
    </div>
  );
}

/** Join class names, dropping falsy parts. */
export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(" ");
}

/* ── Alert: a hairline frame; emphasis from weight, never a hue ── */
.rs-alert{display:flex;gap:10px;border:1px solid var(--divider);border-radius:var(--radius);padding:12px 14px;align-items:flex-start}
.rs-alert svg{flex-shrink:0;margin-top:1px;color:var(--text)}
.rs-alert-title{display:block;font-size:13.5px;font-weight:600;letter-spacing:-.01em;color:var(--text)}
.rs-alert-body{font-size:13px;line-height:1.55;letter-spacing:-.01em;color:var(--text-secondary);margin:2px 0 0}
.rs-alert-solid{background:var(--text);border-color:var(--text)}
.rs-alert-solid svg,.rs-alert-solid .rs-alert-title{color:var(--bg)}
.rs-alert-solid .rs-alert-body{color:var(--bg);opacity:.75}
